def make_trace_spec(args, constructor, attrs, trace_patch):
    if constructor in [go.Scatter, go.Scatterpolar]:
        if "render_mode" in args and (
            args["render_mode"] == "webgl"
            or (
                args["render_mode"] == "auto"
                and len(args["data_frame"]) > 1000
                and args.get("line_shape") != "spline"
                and args["animation_frame"] is None
            )
        ):
            if constructor == go.Scatter:
                constructor = go.Scattergl
                if "orientation" in trace_patch:
                    del trace_patch["orientation"]
            else:
                constructor = go.Scatterpolargl
    # Create base trace specification
    result = [TraceSpec(constructor, attrs, trace_patch, None)]

    # Add marginal trace specifications
    for letter in ["x", "y"]:
        if "marginal_" + letter in args and args["marginal_" + letter]:
            trace_spec = None
            axis_map = dict(
                xaxis="x1" if letter == "x" else "x2",
                yaxis="y1" if letter == "y" else "y2",
            )
            if args["marginal_" + letter] == "histogram":
                marginal_attrs = [letter, "marginal_" + letter]
                marginal_trace_patch = dict(opacity=0.5, bingroup=letter, **axis_map)
                if args.get("z") is not None:
                    marginal_attrs.append("z")
                    marginal_trace_patch["histfunc"] = args.get("histfunc")
                    marginal_trace_patch["orientation"] = "v" if letter == "x" else "h"
                trace_spec = TraceSpec(
                    constructor=go.Histogram,
                    attrs=marginal_attrs,
                    trace_patch=marginal_trace_patch,
                    marginal=letter,
                )
            elif args["marginal_" + letter] == "violin":
                trace_spec = TraceSpec(
                    constructor=go.Violin,
                    attrs=[letter, "hover_name", "hover_data"],
                    trace_patch=dict(scalegroup=letter),
                    marginal=letter,
                )
            elif args["marginal_" + letter] == "box":
                trace_spec = TraceSpec(
                    constructor=go.Box,
                    attrs=[letter, "hover_name", "hover_data"],
                    trace_patch=dict(notched=True),
                    marginal=letter,
                )
            elif args["marginal_" + letter] == "rug":
                symbols = {"x": "line-ns-open", "y": "line-ew-open"}
                trace_spec = TraceSpec(
                    constructor=go.Box,
                    attrs=[letter, "hover_name", "hover_data"],
                    trace_patch=dict(
                        fillcolor="rgba(255,255,255,0)",
                        line={"color": "rgba(255,255,255,0)"},
                        boxpoints="all",
                        jitter=0,
                        hoveron="points",
                        marker={"symbol": symbols[letter]},
                    ),
                    marginal=letter,
                )
            elif args["marginal_" + letter] == "heatmap":
                if constructor != go.Histogram2d:
                    raise ValueError(
                        "`marginal_x`/`marginal_y` value `'heatmap'` is only supported "
                        "for `density_heatmap`."
                    )
                other_letter = "y" if letter == "x" else "x"
                heatmap_trace_patch = dict(
                    coloraxis="coloraxis1", histfunc=args.get("histfunc"), **axis_map
                )
                # `nbinsx`/`nbinsy` are only a target bin count -- plotly.js's "nice
                # number" bin-sizing can still round to more than one bin. Force
                # exactly one bin by setting explicit bin edges covering the data.
                other_col = args["data_frame"].get_column(args[other_letter])
                other_min = nw.to_py_scalar(other_col.min())
                other_max = nw.to_py_scalar(other_col.max())
                span = (other_max - other_min) or 1
                pad = span * 0.001
                other_bins = dict(
                    start=other_min - pad, end=other_max + pad, size=span + 2 * pad
                )
                if letter == "x":
                    heatmap_trace_patch["xbingroup"] = "x"
                    heatmap_trace_patch["ybins"] = other_bins
                else:
                    heatmap_trace_patch["ybingroup"] = "y"
                    heatmap_trace_patch["xbins"] = other_bins
                if args.get("text_auto", False) is not False:
                    if args["text_auto"] is True:
                        heatmap_trace_patch["texttemplate"] = "%{z}"
                    else:
                        heatmap_trace_patch["texttemplate"] = (
                            "%{z:" + args["text_auto"] + "}"
                        )
                trace_spec = TraceSpec(
                    constructor=go.Histogram2d,
                    attrs=[letter, other_letter, "z"],
                    trace_patch=heatmap_trace_patch,
                    marginal=letter,
                )
            else:
                raise ValueError(
                    f"Invalid value '{args['marginal_' + letter]}' for `marginal_{letter}`. "
                    "Supported marginal plot types are: "
                    "'rug', 'box', 'violin', 'histogram', 'heatmap'."
                )
            if trace_spec.constructor != go.Histogram2d and (
                "color" in attrs or "color" not in args
            ):
                if "marker" not in trace_spec.trace_patch:
                    trace_spec.trace_patch["marker"] = dict()
                first_default_color = args["color_continuous_scale"][0]
                trace_spec.trace_patch["marker"]["color"] = first_default_color
            result.append(trace_spec)

    # Add trendline trace specifications
    if args.get("trendline") and args.get("trendline_scope", "trace") == "trace":
        result.append(make_trendline_spec(args, constructor))
    return result


def make_trendline_spec(args, constructor):
    trace_spec = TraceSpec(
        constructor=(
            go.Scattergl
            if constructor == go.Scattergl  # could be contour
            else go.Scatter
        ),
        attrs=["trendline"],
        trace_patch=dict(mode="lines"),
        marginal=None,
    )
    if args["trendline_color_override"]:
        trace_spec.trace_patch["line"] = dict(color=args["trendline_color_override"])
    return trace_spec


