df=pd.DataFrame({'x':[1,2,3,4],'cat':['b','a','b','a'],'y':[10,20,30,40],'c':['A','A','B','B']})
# bar only x categorical counts
for kw in [dict(x='cat'), dict(y='cat'), dict(x='x'),dict(x='cat',y='y',histfunc='sum'),dict(x='cat',y='y',text_auto=True)]:
 try:
  f=px.bar(df,**kw); print('bar',kw,[(t.type,t.orientation,list(t.x) if t.x is not None else None,list(t.y) if t.y is not None else None,t.texttemplate) for t in f.data],f.layout.xaxis.title.text,f.layout.yaxis.title.text,f.layout.barmode)
 except Exception as e:print('ERR',kw,type(e).__name__,e)
# hist aggs
for kw in [dict(x='x'),dict(x='x',y='y'),dict(x='x',y='y',histfunc='sum'),dict(x='cat',y='y',histfunc='sum',histnorm='percent'),dict(x='x',nbins=2),dict(x='x',cumulative=True),dict(x='x',barnorm='percent')]:
 try:
  f=px.histogram(df,**kw); t=f.data[0]; print('hist',kw,list(t.x) if t.x is not None else None,list(t.y) if t.y is not None else None,t.histfunc,t.histnorm,t.nbinsx,f.layout.barnorm,t.cumulative.enabled,f.layout.yaxis.title.text)
 except Exception as e:print('ERR hist',kw,type(e).__name__,e)
# ecdf
for kw in [dict(x='x'),dict(x='x',y='y'),dict(x='x',ecdfnorm=None),dict(x='x',ecdfmode='reversed'),dict(x='x',ecdfmode='complementary'),dict(x='x',orientation='h')]:
 try:
  f=px.ecdf(df,**kw); print('ecdf',kw,[(t.x,t.y,t.orientation) for t in f.data])
 except Exception as e:print('ERR ecdf',kw,type(e).__name__,e)
PY"}

