{"command": "python - <<'PY'
import pandas as pd, plotly.express as px
# hierarchy with ids parents direct
df=pd.DataFrame({'id':['a','b','c'],'parent':['','a','a'],'val':[1,2,3],'lab':['A','B','C']})
for fn in [px.sunburst,px.treemap,px.icicle]:
 f=fn(df,names='lab',parents='parent',ids='id',values='val')
 t=f.data[0]; print(fn.__name__,t.type,list(t.labels),list(t.parents),list(t.ids),list(t.values),t.branchvalues,t.maxdepth)
# path combined error
for fn in [px.sunburst,px.treemap,px.icicle]:
 try: fn(df,path=['id'],ids='id')
 except Exception as e: print(fn.__name__,type(e).__name__,e)
# leaf error
bad=pd.DataFrame({'a':['x',None],'b':['y','z'],'v':[1,2]})
try: px.sunburst(bad,path=['a','b'],values='v')
except Exception as e:print('leaves',type(e).__name__,str(e)[:200])
# nonnumeric values
try: px.sunburst(df,path=['id'],values='lab')
except Exception as e:print('nonnumeric',type(e).__name__,e)
PY"}

