import numpy as np
from plotly.figure_factory import create_trisurf
from plotly.figure_factory import _trisurf as t
x=[0,1,0,1];y=[0,0,1,1];z=[0,1,2,3];simp=[[0,1,2],[1,3,2]]
for cb,pe in [(True,True),(False,False),(True,False),(False,True)]:
 fig=create_trisurf(x,y,z,simp,show_colorbar=cb,plot_edges=pe)
 print('cb,pe',cb,pe,'traces',[(d.type, getattr(d,'name',None)) for d in fig.data], 'len edge', len(fig.data[-1].x) if fig.data[-1].type=='scatter3d' and pe else None)
 print('mesh facecolor',fig.data[0].facecolor)
print('map',t.map_face2color(0,[(0,0,0),(1,1,1)],None,0,1))
print('mapmax',t.map_face2color(1,[(0,0,0),(1,1,1)],None,0,1))
print('mapsingle',t.map_face2color(0.3,[(0,0,0)],None,0,1))
print('mapscale',t.map_face2color(.7,[(0,0,0),(1,1,1)],[0,.5,1],0,1))
