def test_annotation_dict_for_label_positions(row_col, flipped, right_side, expected):
    annotation = utils.annotation_dict_for_label(
        "Label",
        lane=2,
        num_of_lanes=2,
        subplot_spacing=0.1,
        row_col=row_col,
        flipped=flipped,
        right_side=right_side,
        text_color="#123456",
    )

    for key, value in expected.items():
        assert annotation[key] == pytest.approx(value) if isinstance(value, float) else annotation[key] == value

    assert annotation["text"] == "Label"
    assert annotation["showarrow"] is False
    assert annotation["xref"] == "paper"
    assert annotation["yref"] == "paper"
    assert annotation["font"] == {"size": 13, "color": "#123456"}


